 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    def source_index(pos, size):
        tile, offset = divmod(pos, size)
        if tile in (0, 2):
            return size - 1 - offset
        return offset

    return [
        [grid[source_index(y, h)][source_index(x, w)] for x in range(3 * w)]
        for y in range(3 * h)
    ]
